-- Q10: Chronic conditions, patients and average cost per patient
SELECT 'Heart Failure' AS condition, COUNT(*) AS patients,
  ROUND(AVG(MEDREIMB_IP + MEDREIMB_OP + MEDREIMB_CAR), 2) AS avg_cost_per_patient
FROM beneficiary WHERE SP_CHF = 1
UNION ALL SELECT 'Diabetes', COUNT(*), ROUND(AVG(MEDREIMB_IP + MEDREIMB_OP + MEDREIMB_CAR), 2) FROM beneficiary WHERE SP_DIABETES = 1
UNION ALL SELECT 'COPD', COUNT(*), ROUND(AVG(MEDREIMB_IP + MEDREIMB_OP + MEDREIMB_CAR), 2) FROM beneficiary WHERE SP_COPD = 1
UNION ALL SELECT 'Chronic Kidney Disease', COUNT(*), ROUND(AVG(MEDREIMB_IP + MEDREIMB_OP + MEDREIMB_CAR), 2) FROM beneficiary WHERE SP_CHRNKIDN = 1
UNION ALL SELECT 'Ischemic Heart Disease', COUNT(*), ROUND(AVG(MEDREIMB_IP + MEDREIMB_OP + MEDREIMB_CAR), 2) FROM beneficiary WHERE SP_ISCHMCHT = 1
UNION ALL SELECT 'Depression', COUNT(*), ROUND(AVG(MEDREIMB_IP + MEDREIMB_OP + MEDREIMB_CAR), 2) FROM beneficiary WHERE SP_DEPRESSN = 1
UNION ALL SELECT 'Cancer', COUNT(*), ROUND(AVG(MEDREIMB_IP + MEDREIMB_OP + MEDREIMB_CAR), 2) FROM beneficiary WHERE SP_CNCR = 1
UNION ALL SELECT 'Alzheimer / Dementia', COUNT(*), ROUND(AVG(MEDREIMB_IP + MEDREIMB_OP + MEDREIMB_CAR), 2) FROM beneficiary WHERE SP_ALZHDMTA = 1
UNION ALL SELECT 'Stroke / TIA', COUNT(*), ROUND(AVG(MEDREIMB_IP + MEDREIMB_OP + MEDREIMB_CAR), 2) FROM beneficiary WHERE SP_STRKETIA = 1
UNION ALL SELECT 'Osteoporosis', COUNT(*), ROUND(AVG(MEDREIMB_IP + MEDREIMB_OP + MEDREIMB_CAR), 2) FROM beneficiary WHERE SP_OSTEOPRS = 1
UNION ALL SELECT 'Arthritis (RA/OA)', COUNT(*), ROUND(AVG(MEDREIMB_IP + MEDREIMB_OP + MEDREIMB_CAR), 2) FROM beneficiary WHERE SP_RA_OA = 1
ORDER BY avg_cost_per_patient DESC;
